// Подмена ответов AI-функций Supabase (functions/v1/<fn>) через page.route — без настоящего (платного) вызова модели.
// Все POST к функции отвечаются подменой; настоящий запрос к AI из окна теста не уходит никогда (calls.real === 0).
import { Page } from '@playwright/test';

export const BALANCE = 'Your credit balance is too low to access the Anthropic API. Please go to Plans & Billing to upgrade or purchase credits.';

/** Варианты ответа сервера при ошибке модели (#38e1e5): текст о балансе в разных полях, статус 200 и 400; timeout — обычная ошибка. */
export const VARIANTS: Record<string, { status: number; body: unknown; balance: boolean }> = {
  'error-200': { status: 200, body: { ok: false, code: 'MODEL_FAILED', error: BALANCE }, balance: true },
  'error-400': { status: 400, body: { ok: false, code: 'MODEL_FAILED', error: BALANCE }, balance: true },
  'error.message-200': { status: 200, body: { ok: false, code: 'MODEL_FAILED', error: { message: BALANCE } }, balance: true },
  'error.message-400': { status: 400, body: { ok: false, code: 'MODEL_FAILED', error: { message: BALANCE } }, balance: true },
  'message-200': { status: 200, body: { ok: false, code: 'MODEL_FAILED', message: BALANCE }, balance: true },
  'detail-200': { status: 200, body: { ok: false, code: 'MODEL_FAILED', detail: BALANCE }, balance: true },
  'timeout-200': { status: 200, body: { ok: false, code: 'MODEL_FAILED', error: 'Request timed out' }, balance: false },
  'timeout-500': { status: 500, body: { error: 'timeout' }, balance: false },
};

/** Общая часть понятного сообщения о балансе (одинакова во всех AI-местах). */
export const BALANCE_TEXT = 'השירות מושבת זמנית אצל הספק (נגמרה יתרת השימוש), ולכן ניסיון חוזר לא יעזור.';

const CORS = {
  'access-control-allow-origin': '*',
  'access-control-allow-headers': '*',
  'access-control-allow-methods': 'POST, OPTIONS',
  'content-type': 'application/json',
};

/** delay — задержка ответа подмены в мс (имитация опоздавшего ответа модели, #6ac0be); по умолчанию 0. */
export type AiMock = { hits: number; bodies: string[]; delay: number; set: (status: number, body: unknown) => void };

/** Обычный ответ import-map, когда модель ничего не распознала (200, пустой columns). */
export const IMPORT_MAP_EMPTY = { ok: true, columns: [], units: [], categories: [], dropped: 0, model: 'mock' };

/** Подменяет functions/v1/<fn>. Ответ по умолчанию — 500 (чтобы случайный вызов не ушёл в настоящий AI). */
export async function mockAi(page: Page, fn: string, status = 500, body: unknown = { error: 'not mocked' }): Promise<AiMock> {
  const st: AiMock = { hits: 0, bodies: [], delay: 0, set: (s, b) => { status = s; body = b; } };
  await page.route(`**/functions/v1/${fn}*`, async (route) => {
    const req = route.request();
    if (req.method() === 'OPTIONS') return route.fulfill({ status: 204, headers: CORS, body: '' });
    st.hits++;
    st.bodies.push((req.postData() || '').slice(0, 300));
    const [s, b] = [status, body];
    if (st.delay) await new Promise((r) => setTimeout(r, st.delay));
    return route.fulfill({ status: s, headers: CORS, body: JSON.stringify(b) }).catch(() => { /* окно уже закрыто */ });
  });
  return st;
}

const WRITE_RPC = /\/rpc\/(create|update|delete|insert|upsert|set|approve|reject|cart|place|receive|import|save)/i;

/** Блокирует запись в базу из окна теста (POST/PATCH/DELETE к таблицам rest/v1 и «пишущие» rpc) и считает попытки.
 *  Читающие rpc (проверка остатка/цены и т.п.) пропускаются. */
export async function blockWrites(page: Page) {
  const writes: string[] = [];
  await page.route('**/rest/v1/**', (route) => {
    const req = route.request();
    const url = req.url();
    const isRpc = url.includes('/rest/v1/rpc/');
    if (req.method() === 'GET' || req.method() === 'HEAD' || (isRpc && !WRITE_RPC.test(url))) return route.fallback();
    writes.push(`${req.method()} ${url.split('?')[0]}`);
    return route.abort();
  });
  return writes;
}
